Para resolver este problema de forma eficiente, podemos analisar as condições sob as quais uma string $S_k$ pode ser substring da concatenação $S_a S_b$ ($a, b < k$):

1. **$S_k$ está contida inteiramente em $S_a$ ou em $S_b$**: isso ocorre se $S_k$ for uma substring de alguma string anterior. Como as strings têm tamanho até 10, cada string anterior possui no máximo 55 substrings distintas.
2. **$S_k$ cruza a fronteira entre $S_a$ e $S_b$**: isso ocorre se existir uma divisão de $S_k$ em duas partes não vazias, $P$ e $Q$ ($S_k = P + Q$), de modo que $P$ seja sufixo de alguma string anterior $S_a$ e $Q$ seja prefixo de alguma string anterior $S_b$. Note que a escolha de $S_a$ e $S_b$ é independente.

Como todas as strings têm tamanho no máximo 10 letras minúsculas, podemos codificar qualquer substring de forma bijetiva (sem colisões) em um único inteiro de 64 bits (`uint64_t`), usando 5 bits por caractere ($10 \times 5 = 50 \text{ bits} \le 64 \text{ bits}$). Isso torna as operações de busca e inserção em tabelas hash extremamente rápidas.

Abaixo está a solução completa em C++:

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>

using namespace std;

// Codifica uma string de até 12 caracteres minúsculos em um uint64_t de forma bijetiva
uint64_t encode(const string& s, int start, int len) {
    uint64_t code = 0;
    for (int i = 0; i < len; ++i) {
        code = (code << 5) | (s[start + i] - 'a' + 1);
    }
    return code;
}

uint64_t encode(const string& s) {
    return encode(s, 0, s.length());
}

int main() {
    // Otimização de I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> s(n);
    for (int i = 0; i < n; ++i) {
        cin >> s[i];
    }

    unordered_set<uint64_t> prefixes;
    unordered_set<uint64_t> suffixes;
    unordered_set<uint64_t> all_substrings;

    // Pré-reserva de espaço para evitar rehashes frequentes
    prefixes.reserve(100000);
    suffixes.reserve(100000);
    all_substrings.reserve(600000);

    for (int k = 0; k < n; ++k) {
        int len = s[k].length();
        bool invalid = false;

        // Caso 1: S_k é substring de alguma string anterior
        if (all_substrings.count(encode(s[k]))) {
            invalid = true;
        }

        // Caso 2: S_k cruza a fronteira entre S_a e S_b
        if (!invalid) {
            for (int i = 1; i < len; ++i) {
                uint64_t pref_part = encode(s[k], 0, i);
                uint64_t suff_part = encode(s[k], i, len - i);

                if (suffixes.count(pref_part) && prefixes.count(suff_part)) {
                    invalid = true;
                    break;
                }
            }
        }

        if (invalid) {
            cout << s[k] << "\n";
            return 0;
        }

        // Adiciona todos os prefixos de s[k]
        for (int i = 1; i <= len; ++i) {
            prefixes.insert(encode(s[k], 0, i));
        }

        // Adiciona todos os sufixos de s[k]
        for (int i = 1; i <= len; ++i) {
            suffixes.insert(encode(s[k], len - i, i));
        }

        // Adiciona todas as substrings de s[k]
        for (int i = 0; i < len; ++i) {
            for (int l = 1; i + l <= len; ++l) {
                all_substrings.insert(encode(s[k], i, l));
            }
        }
    }

    cout << "ok\n";
    return 0;
}
```

